modded class DGBNativeGroundBody {
    ref array<dBlock> NFInternalBlocks=new array<dBlock>;
override void Initialize(int id,DGBNativeGroundDirector director,vector point)
    {
        if(!FileExist("$profile:nf-network-body.flag")){super.Initialize(id,director,point);return;}
        if(!GetGame().IsServer() || !GetGame().IsMultiplayer()){Print("NF_NETWORK_BODY_FAILED role");return;}
        if(!director.RepartitionModel || !director.Vertical || director.RenderPartCount!=8)
        {Print("DG_SUBSET_INTEGRATION_FAILED unsupported_director");return;}

        Id=id;Director=director;
        for(int part=0;part<director.RenderPartCount;part++)
        {
            string bodyType="NFNetPartsPart"+part;
            if(part==0){bodyType="DGSubsetIntegratedCrowdLeader";}
            int creationFlags=ECE_CREATEPHYSICS;
            Animal_DGNativeProbe actor=Animal_DGNativeProbe.Cast(GetGame().CreateObjectEx(bodyType,point,creationFlags));

    else if(director.SimulationLod>=0)actor.UpdateSimulationPrecision(director.SimulationLod);
    actor.SetOrientation("180 0 0");
    if(dBodyIsSet(actor))
    {
        foreach(Animal_DGNativeProbe sibling:Parts)
        {
            if(!dBodyIsSet(sibling)){Print("NF_NETWORK_BODY_FAILED sibling_physics");return;}
            dBlock siblingBlock=dBodyCollisionBlock(actor,sibling);
            if(!siblingBlock){Print("NF_NETWORK_BODY_FAILED sibling_block");return;}
            NFInternalBlocks.Insert(siblingBlock);
        }
    }
    else{Print("NF_NETWORK_BODY_FAILED actor_physics");return;}
    Parts.Insert(actor);
    if(part==0)Leader=actor;
}
if(!Leader)return;
if(director.CombatEnabled)

{
    DamageReceiver=Animal_DGNativeProbe.Cast(GetGame().CreateObjectEx("Animal_DGNativeDamageReceiver",point,ECE_CREATEPHYSICS));
    if(!DamageReceiver)return;
    if(!dBodyIsSet(DamageReceiver)){Print("NF_NETWORK_BODY_FAILED receiver_physics");return;}
    foreach(Animal_DGNativeProbe renderSibling:Parts)
    {
        dBlock receiverBlock=dBodyCollisionBlock(renderSibling,DamageReceiver);
        if(!receiverBlock){Print("NF_NETWORK_BODY_FAILED receiver_block");return;}
        NFInternalBlocks.Insert(receiverBlock);
    }
    DamageReceiver.GroundBody=this;DamageReceiver.DamageReceiver=true;DamageReceiver.SetAllowDamage(true);
    DamageReceiver.RuntimeTimingProbe=director.RuntimeTimingProbe;
    DamageReceiver.SetOrientation("180 0 0");
    if(director.ResetSimulationPrecision)DamageReceiver.UpdateSimulationPrecision(-1);
    else if(director.SimulationLod>=0)DamageReceiver.UpdateSimulationPrecision(director.SimulationLod);
}
Agent.Initialize(Leader);Agent.UseNativeRootDelta=true;
if(director.CrowdDynamics){Agent.PeerCoreDistance=0.58;Agent.CollisionPlayers=director.PerceivedPlayers;}

Agent.SenseAt=Director.Now+Id*0.02;
array<string> names={"Hips","Head","LeftFoot","RightFoot"};
foreach(string name:names)
{
    int requiredBone=Leader.GetBoneIndexByName(name);
    // Bone handles are opaque signed IDs. RightFoot legitimately has
    // a negative handle; only the API's -1 sentinel is unavailable.
    if(requiredBone==-1){Print("DG_NATIVE_REQUIRED_BONE_MISSING "+name);return;}
    JointIds.Insert(requiredBone);
}
EntityId=Leader.GetBoneIndexByName("EntityPosition");
if(EntityId==-1){Print("DG_NATIVE_REQUIRED_BONE_MISSING EntityPosition");return;}
NativeSkeletonReady=true;
Agent.ObstacleMin.Copy(Director.ObstacleMin);Agent.ObstacleMax.Copy(Director.ObstacleMax);
if(director.Vertical)Traversal=new DGBNativeTraversal(this);
if(director.CombatEnabled)Combat=new DGBNativeCombat(this);
